def reverse_string(s):
    """Return the characters of s in reverse order."""
    # Reject non-string input early so the slicing below cannot fail silently
    if not isinstance(s, str):
        raise TypeError("reverse_string() expects a str, got %s" % type(s).__name__)
    # A negative-step slice copies the sequence back-to-front in one pass
    return s[::-1]


def reverse_words(sentence):
    """Reverse the order of whitespace-separated words, keeping each word intact."""
    words = sentence.split()
    # split() already collapsed the runs of whitespace, so a single space rejoins cleanly
    return " ".join(reversed(words))


def is_palindrome(s, ignore_case=True, letters_only=True):
    """Report whether s reads the same forwards and backwards."""
    candidate = s
    if letters_only:
        # Punctuation and spaces would otherwise break phrases like "A man, a plan, a canal"
        candidate = "".join(ch for ch in candidate if ch.isalnum())
    if ignore_case:
        candidate = candidate.casefold()
    return candidate == reverse_string(candidate)


def reverse_preserving_case_pattern(s):
    """Reverse the letters of s but keep the original upper/lower pattern in place."""
    reversed_chars = list(reverse_string(s))
    for index, original in enumerate(s):
        # Only alphabetic positions carry a meaningful case to restore
        if not original.isalpha():
            continue
        if original.isupper():
            reversed_chars[index] = reversed_chars[index].upper()
        else:
            reversed_chars[index] = reversed_chars[index].lower()
    return "".join(reversed_chars)


def format_report(samples):
    """Build a human-readable report line for each sample string."""
    lines = []
    # Align the quoted originals so the arrows line up in the output
    width = max((len(repr(sample)) for sample in samples), default=0)
    for sample in samples:
        flipped = reverse_string(sample)
        marker = "palindrome" if is_palindrome(sample) else "not a palindrome"
        lines.append("%-*s -> %-14s (%s)" % (width, repr(sample), repr(flipped), marker))
    return "\n".join(lines)


def main():
    samples = ["hello", "Python", "", "a", "Never odd or even"]
    print(format_report(samples))

    sentence = "the quick brown fox"
    # Word-level reversal differs from character-level reversal, so show both
    print("words reversed:", reverse_words(sentence))
    print("chars reversed:", reverse_string(sentence))

    title = "Hello World"
    # The case pattern stays H....W.... even though the letters moved
    print("case-preserving:", reverse_preserving_case_pattern(title))


if __name__ == "__main__":
    main()

