VOWELS = frozenset("aeiou")


def count_vowels(text):
    # Reject non-string input early so callers get a clear error instead of a confusing failure later
    if not isinstance(text, str):
        raise TypeError("count_vowels() expects a string, got %s" % type(text).__name__)
    total = 0
    for char in text:
        # Lowercasing each character makes the membership test case-insensitive
        if char.lower() in VOWELS:
            total += 1
    return total


def vowel_breakdown(text):
    # Start every vowel at zero so the report has a stable, sorted set of keys
    counts = {vowel: 0 for vowel in sorted(VOWELS)}
    for char in text.lower():
        # Only the five tracked keys exist, so anything that is not a vowel is skipped
        if char in counts:
            counts[char] += 1
    return counts


def vowel_ratio(text):
    letters = sum(1 for char in text if char.isalpha())
    # An empty or digit-only string has no letters, so define the ratio as zero
    if letters == 0:
        return 0.0
    return count_vowels(text) / letters


def format_report(text):
    total = count_vowels(text)
    breakdown = vowel_breakdown(text)
    # Mention only the vowels that actually appear, keeping the report compact
    present = ["%s=%d" % (vowel, n) for vowel, n in breakdown.items() if n]
    detail = ", ".join(present) if present else "none"
    lines = [
        "Input      : %r" % text,
        "Vowels     : %d" % total,
        "Breakdown  : %s" % detail,
        # Percentages read better than raw ratios in a printed report
        "Vowel share: %.1f%% of letters" % (vowel_ratio(text) * 100.0),
    ]
    return "\n".join(lines)


def main():
    samples = [
        "Hello World",
        "Python",
        "AEIOU aeiou",
        "rhythm",
        "",
    ]
    for index, sample in enumerate(samples):
        # Separate consecutive reports with a blank line, but not before the first one
        if index:
            print()
        print(format_report(sample))
    grand_total = sum(count_vowels(sample) for sample in samples)
    print()
    print("Total vowels across %d samples: %d" % (len(samples), grand_total))


if __name__ == "__main__":
    main()

