# Utilities for finding the largest integer in a list, plus a small report driver.


def find_max(numbers):
    # Track the running maximum instead of sorting, so a single pass suffices.
    largest = numbers[0]
    for value in numbers[1:]:
        # Strict comparison keeps the first occurrence of a repeated maximum.
        if value > largest:
            largest = value
    return largest


def parse_numbers(text):
    # Commas are turned into spaces so both separators work with one split call.
    cleaned = text.replace(",", " ")
    numbers = []
    for token in cleaned.split():
        try:
            numbers.append(int(token))
        except ValueError:
            # Re-raise with the offending token, which is far more useful to a caller.
            raise ValueError("not an integer: {!r}".format(token))
    return numbers


def validate(numbers):
    # find_max indexes element 0, so an empty list must be rejected up front.
    if not numbers:
        raise ValueError("the list of numbers is empty")
    return numbers


def index_of_max(numbers):
    # list.index finds the first match, which is the same element find_max keeps.
    return numbers.index(find_max(numbers))


def describe(numbers):
    validate(numbers)
    largest = find_max(numbers)
    position = index_of_max(numbers)
    # Positions are reported one-based because the summary is for human readers.
    return "max({}) = {} at position {}".format(
        ", ".join(str(n) for n in numbers), largest, position + 1
    )


def main():
    datasets = ["10, 5, 20, 8", "7", "-4 -9 -1 -30", "3 3 3", ""]
    for raw in datasets:
        try:
            numbers = parse_numbers(raw)
            print(describe(numbers))
        except ValueError as error:
            # Bad input should not abort the whole report, only skip that line.
            print("skipping {!r}: {}".format(raw, error))


if __name__ == "__main__":
    main()

