ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    # Reject booleans explicitly: bool is a subclass of int but not a temperature
    if isinstance(celsius, bool) or not isinstance(celsius, (int, float)):
        raise TypeError("celsius must be an int or float, got %r" % (celsius,))
    # Nothing colder than absolute zero can exist, so treat it as bad input
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError("temperature below absolute zero: %r" % (celsius,))
    # Multiply before dividing keeps integer inputs exact under true division
    return celsius * 9 / 5 + 32


def parse_celsius(text):
    # Accept human input such as " 25 C" or "-40°c" by trimming the unit suffix
    cleaned = text.strip().rstrip("Cc").rstrip("°").strip()
    if not cleaned:
        raise ValueError("no temperature found in %r" % (text,))
    return float(cleaned)


def format_conversion(celsius, decimals=1):
    fahrenheit = celsius_to_fahrenheit(celsius)
    # Fixed-width columns keep the report readable for negative values too
    return "{:>9.{p}f} C = {:>9.{p}f} F".format(celsius, fahrenheit, p=decimals)


def conversion_table(start, stop, step=10):
    # A non-positive step would loop forever (or produce nothing at all)
    if step <= 0:
        raise ValueError("step must be positive")
    rows = []
    current = start
    while current <= stop:
        rows.append(format_conversion(current))
        # Recompute from the start to avoid accumulating float rounding error
        current = start + step * (len(rows))
    return rows


def convert_all(texts):
    results = []
    for text in texts:
        try:
            celsius = parse_celsius(text)
            results.append((text, celsius_to_fahrenheit(celsius)))
        except (TypeError, ValueError) as exc:
            # Keep processing the remaining inputs; report the failure inline
            results.append((text, str(exc)))
    return results


def main():
    inputs = ["0", "25 C", "-40°C", "100", "-300", "warm"]
    for text, outcome in convert_all(inputs):
        # Numeric outcomes were converted; strings carry the error message
        if isinstance(outcome, float):
            print("{:>8} -> {:.1f} F".format(text, outcome))
        else:
            print("{:>8} -> error: {}".format(text, outcome))

    print()
    print("Conversion table")
    for row in conversion_table(-20, 40, 20):
        print(row)


if __name__ == "__main__":
    main()

