def count_lines_in_file(filepath):
    total = 0
    trailing_byte = b""
    # Read in binary mode and count newline bytes: this avoids loading the
    # whole file into memory and sidesteps text-decoding errors entirely.
    with open(filepath, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 16), b""):
            total += chunk.count(b"\n")
            trailing_byte = chunk[-1:]
    # A final line without a terminating newline still counts as a line.
    if trailing_byte and trailing_byte != b"\n":
        total += 1
    return total


def count_lines_in_files(filepaths):
    # Pair each path with its count, preserving the order given by the caller.
    counts = []
    for path in filepaths:
        counts.append((path, count_lines_in_file(path)))
    return counts


def collect_text_files(directory, suffixes=(".txt", ".py")):
    found = []
    for name in sorted(os.listdir(directory)):
        full = os.path.join(directory, name)
        # Directories and broken symlinks have no lines to count.
        if not os.path.isfile(full):
            continue
        if name.endswith(suffixes):
            found.append(full)
    return found


def format_report(counts):
    if not counts:
        return "no files to report"
    # Align the numbers by padding every path to the longest one.
    width = max(len(path) for path, _ in counts)
    lines = []
    for path, count in counts:
        lines.append("%-*s %6d" % (width, path, count))
    grand_total = sum(count for _, count in counts)
    lines.append("%-*s %6d" % (width, "TOTAL", grand_total))
    return "\n".join(lines)


def main(argv):
    targets = []
    # Without arguments the current directory is the implied target.
    for arg in argv[1:] or ["."]:
        if os.path.isdir(arg):
            targets.extend(collect_text_files(arg))
        else:
            targets.append(arg)
    missing = [path for path in targets if not os.path.exists(path)]
    if missing:
        # Report unreadable paths on stderr rather than crashing mid-count.
        print("skipping missing files: " + ", ".join(missing), file=sys.stderr)
        targets = [path for path in targets if path not in missing]
    print(format_report(count_lines_in_files(targets)))
    # A non-zero status lets shell callers notice the skipped paths.
    return 1 if missing else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

