def guess_number(secret_number, guess):
    # Reject non-integers early so the ordering comparisons stay meaningful
    if not isinstance(secret_number, int) or not isinstance(guess, int):
        raise TypeError("secret_number and guess must be integers")
    if guess > secret_number:
        return 'Too high'
    if guess < secret_number:
        return 'Too low'
    return 'Correct!'


def parse_guess(text):
    # Turn raw user input into an integer, or return None when it is not a number
    cleaned = text.strip()
    # A leading sign is allowed, but the rest must be made of digits
    if cleaned.startswith(('+', '-')):
        body = cleaned[1:]
    else:
        body = cleaned
    if not body.isdigit():
        return None
    return int(cleaned)


def narrow_bounds(low, high, guess, verdict):
    # Shrink the search interval according to the verdict for a guess
    if verdict == 'Too high':
        # Everything from the guess upwards is impossible now
        return low, guess - 1
    if verdict == 'Too low':
        return guess + 1, high
    return guess, guess


def solve(secret_number, low=1, high=100):
    # Binary-search the secret number and collect the guesses with their verdicts
    if low > high:
        raise ValueError("empty search range")
    attempts = []
    while True:
        # The midpoint keeps the remaining interval as small as possible
        guess = (low + high) // 2
        verdict = guess_number(secret_number, guess)
        attempts.append((guess, verdict))
        if verdict == 'Correct!':
            return attempts
        low, high = narrow_bounds(low, high, guess, verdict)


def format_round(index, guess, verdict):
    # Build a single human-readable report line
    return "Attempt {0}: {1} -> {2}".format(index, guess, verdict)


def play(secret_number, guesses):
    # Run the game over a sequence of raw inputs and report each round
    lines = []
    round_number = 0
    for raw in guesses:
        value = parse_guess(raw)
        # Invalid input does not consume an attempt, it is only reported
        if value is None:
            lines.append("Ignored {0!r}: not a whole number".format(raw))
            continue
        round_number += 1
        verdict = guess_number(secret_number, value)
        lines.append(format_round(round_number, value, verdict))
        if verdict == 'Correct!':
            break
    else:
        # The loop ended without a correct guess, so reveal the answer
        lines.append("Out of guesses, the number was {0}".format(secret_number))
    return lines


def main():
    for line in play(10, ["12", "seven", "8", "10", "11"]):
        print(line)
    attempts = solve(73, 1, 100)
    print("Binary search found 73 in {0} attempts".format(len(attempts)))
    for index, (guess, verdict) in enumerate(attempts, start=1):
        print(format_round(index, guess, verdict))


if __name__ == '__main__':
    main()

