def roman_to_int(roman_numeral):
    # Define a dictionary to map Roman numeral characters to their integer values.
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_value = 0  # Initialize the total integer value.
    prev_value = 0  # Initialize the value of the previously processed numeral.

    # Iterate through the Roman numeral string from right to left.
    for char in reversed(roman_numeral):
        current_value = roman_map[char]  # Get the integer value of the current character.

        # If the current value is less than the previous value, subtract it (e.g., 'IV').
        if current_value < prev_value:
            integer_value -= current_value
        else:
            # Otherwise, add the current value to the total.
            integer_value += current_value
        prev_value = current_value  # Update the previous value for the next iteration.

    return integer_value  # Return the final integer representation.

