# Utilities for computing the difference between two lists.


def _as_lookup(values):
    try:
        # A set gives O(1) membership, which keeps the difference linear.
        return set(values)
    except TypeError:
        # Unhashable items (lists, dicts, ...) force a fallback to the list itself.
        return list(values)


def list_difference(list1, list2):
    # Guard against non-list inputs before any membership work is done.
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("both arguments must be lists")
    lookup = _as_lookup(list2)
    difference_list = []
    for item in list1:
        # Duplicates of list1 are preserved, mirroring plain list semantics.
        if item not in lookup:
            difference_list.append(item)
    return difference_list


def symmetric_difference(list1, list2):
    # Reusing list_difference in both directions keeps the rules identical.
    return list_difference(list1, list2) + list_difference(list2, list1)


def common_elements(list1, list2):
    lookup = _as_lookup(list2)
    return [item for item in list1 if item in lookup]


def format_report(list1, list2):
    only_first = list_difference(list1, list2)
    only_second = list_difference(list2, list1)
    shared = common_elements(list1, list2)
    lines = [
        "list1 = {0}".format(list1),
        "list2 = {0}".format(list2),
        "only in list1: {0}".format(only_first),
