# Utilidades para calcular la diferencia entre dos listas.


def _as_lookup(values):
    try:
        # Un conjunto ofrece pertenencia O(1), lo que mantiene la diferencia lineal.
        return set(values)
    except TypeError:
        # Los elementos no hashables (listas, diccionarios, ...) obligan a recurrir a la propia lista.
        return list(values)


def list_difference(list1, list2):
    # Protege contra entradas que no sean listas antes de hacer cualquier trabajo de pertenencia.
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("both arguments must be lists")
    lookup = _as_lookup(list2)
    difference_list = []
    for item in list1:
        # Los duplicados de list1 se conservan, reflejando la semántica simple de las listas.
        if item not in lookup:
            difference_list.append(item)
    return difference_list


def symmetric_difference(list1, list2):
    # Reutilizar list_difference en ambas direcciones mantiene las reglas idénticas.
    return list_difference(list1, list2) + list_difference(list2, list1)


def common_elements(list1, list2):
