def update_dict(dict1, dict2):
    # Merge dict2 into a copy of dict1 and return the result
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("both arguments must be dictionaries")
    # Copy first so the caller's original mapping is never mutated
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        # Assignment covers both cases: overwrite an existing key or add a new one
        merged_dict[key] = value
    return merged_dict


def classify_keys(dict1, dict2):
    # Split the keys of dict2 into those that overwrite and those that are new
    overwritten = []
    added = []
    for key in dict2:
        # Membership in dict1 decides whether the key is an update or an addition
        if key in dict1:
            overwritten.append(key)
        else:
            added.append(key)
    # Sorting by string form keeps the report stable for mixed key types
    overwritten.sort(key=repr)
    added.sort(key=repr)
    return overwritten, added


def format_dict(mapping):
    # Render a mapping with keys in insertion order, as a readable literal
    parts = ["{!r}: {!r}".format(key, value) for key, value in mapping.items()]
    return "{" + ", ".join(parts) + "}"


