import secrets
import sys

# Digits are kept as a module-level constant so every helper draws from the same alphabet.
DIGITS = "0123456789"


def generate_pin(length):
    # Booleans are ints in Python, so they are rejected before the range check.
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an int")
    # A PIN of zero or negative length has no meaning, so reject it outright.
    if length < 1:
        raise ValueError("length must be at least 1")
    # secrets.choice is used instead of random.choice because PINs are credentials.
    return "".join(secrets.choice(DIGITS) for _ in range(length))


def has_repeated_run(pin, run_length=3):
    streak = 1
    for previous, current in zip(pin, pin[1:]):
        # Extend the current streak while the digit stays the same, otherwise restart it.
        if current == previous:
            streak += 1
            if streak >= run_length:
                return True
        else:
            streak = 1
    return False


def is_sequential(pin):
    if len(pin) < 2:
        return False
    steps = {int(b) - int(a) for a, b in zip(pin, pin[1:])}
    # A single step of +1 or -1 across the whole string means it is a plain sequence.
    return steps in ({1}, {-1})


def generate_strong_pin(length, attempts=50):
    pin = generate_pin(length)
    for _ in range(attempts):
        if not has_repeated_run(pin) and not is_sequential(pin):
            return pin
        # The candidate looked guessable, so draw a completely fresh one.
        pin = generate_pin(length)
    # Two digit PINs can be unavoidably "sequential", so return the last draw anyway.
    return pin


def describe_pin(pin):
    distinct = len(set(pin))
    flags = []
    if has_repeated_run(pin):
        flags.append("repeated-run")
    if is_sequential(pin):
        flags.append("sequential")
    # An empty flag list is nicer to read as an explicit word than as nothing at all.
    notes = ", ".join(flags) if flags else "none"
    return f"{pin} (length {len(pin)}, {distinct} distinct digits, weaknesses: {notes})"


def parse_lengths(args):
    if not args:
        return [4, 6, 8]
    # Non numeric arguments would crash int(), so report them as a usage error.
    for arg in args:
        if not arg.isdigit():
            raise ValueError(f"not a valid length: {arg}")
    return [int(arg) for arg in args]


def main():
    try:
        lengths = parse_lengths(sys.argv[1:])
    except ValueError as error:
        # Usage mistakes belong on stderr with a non zero exit status.
        print(f"error: {error}", file=sys.stderr)
        return 2
    for length in lengths:
        print(describe_pin(generate_strong_pin(length)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

