def has_unique_chars(text):
    # Guard against non-string input so the scan below is well defined
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    seen = set()
    for ch in text:
        # A repeat means we can stop immediately, no need to scan the rest
        if ch in seen:
            return False
        seen.add(ch)
    # An empty string trivially has no repeated characters
    return True


def find_duplicates(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    seen = set()
    duplicates = []
    for ch in text:
        # Record each offender once, keeping the order of discovery
        if ch in seen and ch not in duplicates:
            duplicates.append(ch)
        seen.add(ch)
    return duplicates


def describe_char(ch):
    # Printable characters are shown as-is; everything else as an escape
    if ch.isprintable():
        return repr(ch)
    return "\\u%04x" % ord(ch)


def format_report(text):
    if has_unique_chars(text):
        return "%r -> unique (%d chars)" % (text, len(text))
    offenders = find_duplicates(text)
    # Join the escaped forms so control characters do not break the layout
    listed = ", ".join(describe_char(ch) for ch in offenders)
    return "%r -> not unique; repeated: %s" % (text, listed)


def main():
    samples = [
        "abcde",
        "hello",
        "",
        "AaBbCc",
        "AaBbCcA",
        "tab\there",
        "tab\tand\ttab",
    ]
