# Utilities for analysing character frequencies in a piece of text.

from collections import Counter


def char_counts(text):
    """Return a Counter mapping each character of *text* to its frequency."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Counter preserves first-insertion order for equal counts, which the
    # "first one encountered" tie-break rule relies on.
    return Counter(text)


def least_frequent_char(text):
    """Return the character occurring least often; ties go to the first seen."""
    counts = char_counts(text)
