def parse_numbers(raw):
    cleaned = raw.replace(",", " ")
    values = []
    for token in cleaned.split():
        # int() already handles a leading sign, so negatives need no special case.
        values.append(int(token))
    return values


def validate_numbers(numbers):
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list of integers")
    for value in numbers:
        # bool is a subclass of int, but True/False are not meaningful data here.
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("numbers must contain integers only")
    # An empty list has no largest element at all, so it cannot be ranked.
    if not numbers:
        raise ValueError("numbers must not be empty")


def find_third_largest(numbers):
    validate_numbers(numbers)
    # Deduplicate first: a repeated value must not occupy two ranking positions.
    distinct = sorted(set(numbers), reverse=True)
    if len(distinct) < 3:
        # With fewer than three distinct values the task asks for the maximum.
        return distinct[0]
    return distinct[2]


def rank_report(numbers):
    result = find_third_largest(numbers)
    distinct_count = len(set(numbers))
    if distinct_count < 3:
        reason = "only %d distinct value(s), returned the largest" % distinct_count
    else:
