def merge_dicts(dict1, dict2):
    # Reject non-dict inputs early so the caller gets a clear error instead of
    # a confusing failure later during iteration.
    if not isinstance(dict1, dict):
        raise TypeError("dict1 must be a dict, got " + type(dict1).__name__)
    if not isinstance(dict2, dict):
        raise TypeError("dict2 must be a dict, got " + type(dict2).__name__)
    # Start from a shallow copy so the original dict1 is never mutated.
    merged = dict(dict1)
    # Writing dict2 last is what gives it priority on shared keys.
    merged.update(dict2)
    return merged


def overwritten_keys(dict1, dict2):
    # Collect the keys of dict1 whose values dict2 replaces with a new value.
    changed = []
    for key, old_value in dict1.items():
        # A key present in both only counts as overwritten when the value differs.
        if key in dict2 and dict2[key] != old_value:
            changed.append(key)
    return changed


def merge_many(dicts):
    # Fold the sequence left to right so later dictionaries win.
    result = {}
    for current in dicts:
        # Reuse merge_dicts so the type validation applies to every element.
        result = merge_dicts(result, current)
    return result


def format_dict(mapping):
    # Sorting the keys keeps the rendered output stable and comparable.
    try:
        keys = sorted(mapping)
    except TypeError:
        # Mixed key types are not orderable, so fall back to insertion order.
        keys = list(mapping)
    body = ", ".join("{!r}: {!r}".format(key, mapping[key]) for key in keys)
    return "{" + body + "}"


def format_merge_report(dict1, dict2):
    # Summarise one merge: the result plus which keys arrived or were replaced.
    merged = merge_dicts(dict1, dict2)
    added = [key for key in dict2 if key not in dict1]
    changed = overwritten_keys(dict1, dict2)
    lines = ["merged: " + format_dict(merged)]
    # Only mention the categories that actually apply, to keep the report short.
    if added:
        lines.append("added keys: " + ", ".join(sorted(map(str, added))))
    if changed:
        lines.append("overwritten keys: " + ", ".join(sorted(map(str, changed))))
    return "\n".join(lines)


def main():
    print(format_merge_report({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
    print(format_merge_report({'x': 10}, {'y': 20}))
    defaults = {'host': 'localhost', 'port': 80, 'debug': False}
    profile = {'port': 8080}
    overrides = {'debug': True}
    # The layers are ordered from weakest to strongest so overrides win.
    config = merge_many([defaults, profile, overrides])
    print("config: " + format_dict(config))


if __name__ == "__main__":
    main()

