ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    # Values colder than absolute zero cannot describe a real temperature.
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError("temperature below absolute zero: {!r}".format(celsius))
    # Dividing by 5 in floating point promotes integer inputs to float.
    return celsius * 9 / 5 + 32


def fahrenheit_to_celsius(fahrenheit):
    # Inverse of the conversion above, used to verify round trips.
    return (fahrenheit - 32) * 5 / 9


def parse_celsius(text):
    # Tolerate a trailing unit letter and surrounding blanks, as in " 30 C ".
    cleaned = text.strip().rstrip("cC").strip()
    if not cleaned:
        raise ValueError("empty temperature string")
    return float(cleaned)


def format_pair(celsius, fahrenheit):
    # One decimal is precise enough for a human-readable table.
    return "{:>9.1f} C = {:>9.1f} F".format(celsius, fahrenheit)


def conversion_table(values):
    # Build one formatted report line per Celsius value.
    lines = []
    for celsius in values:
        fahrenheit = celsius_to_fahrenheit(celsius)
        lines.append(format_pair(celsius, fahrenheit))
    return lines


def find_equal_point(low=-100.0, high=100.0, tolerance=1e-9):
    # Locate the temperature at which both scales show the same number;
    # the difference F(c) - c is monotonic, so bisection converges.
    while high - low > tolerance:
        mid = (low + high) / 2
        if celsius_to_fahrenheit(mid) - mid > 0:
            high = mid
        else:
            low = mid
    return (low + high) / 2


def main(argv):
    # Fall back to a small default set when no arguments are supplied.
    raw_inputs = argv[1:] or ["0", "100", "-40", " 36.6 ", "21C"]
    values = [parse_celsius(item) for item in raw_inputs]
    for line in conversion_table(values):
        print(line)

    boiling_f = celsius_to_fahrenheit(100)
    print("100 C converted back:", fahrenheit_to_celsius(boiling_f))

    equal_point = find_equal_point()
    print("scales meet near {:.4f} degrees".format(equal_point))


if __name__ == "__main__":
    import sys

    main(sys.argv)

