import re
from collections import defaultdict

# The local part accepts the characters commonly allowed by mail providers,
# while the domain must end with a dot followed by a 2+ letter TLD.
EMAIL_RE = re.compile(
    r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}"
)


def is_plausible(address):
    local, domain = address.rsplit("@", 1)
    # A dot may neither open nor close the local part.
    if local.startswith(".") or local.endswith("."):
        return False
    # Consecutive dots are invalid on both sides of the "@".
    return ".." not in local and ".." not in domain


def extract_emails(text):
    # Callers sometimes pass parsed JSON values, so reject non-strings loudly.
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    results = []
    pos = 0
    # Walk the text match by match so the scan position stays explicit.
    while (match := EMAIL_RE.search(text, pos)) is not None:
        pos = match.end()
        address = match.group(0)
        if is_plausible(address):
            results.append(address)
    return results


def unique_emails(text):
    seen = set()
    result = []
    for address in extract_emails(text):
        # Domains are case-insensitive and mailboxes are in practice too.
        key = address.lower()
        if key not in seen:
            seen.add(key)
            result.append(address)
    return result


def group_by_domain(text):
    groups = defaultdict(list)
    for address in unique_emails(text):
        local, domain = address.rsplit("@", 1)
        groups[domain.lower()].append(local)
    # Sorting keeps the report deterministic across runs.
    return {domain: sorted(names) for domain, names in sorted(groups.items())}


def format_report(text):
    groups = group_by_domain(text)
    if not groups:
        return "No email addresses found."
    lines = []
    for domain, names in groups.items():
        # Long mailbox lists are truncated so that one domain stays on one line.
        extra = len(names) - 3
        if extra > 0:
            lines.append("{}: {} (+{} more)".format(domain, ", ".join(names[:3]), extra))
        else:
            lines.append("{}: {}".format(domain, ", ".join(names)))
    total = sum(len(names) for names in groups.values())
    lines.append("Total unique addresses: {}".format(total))
    return "\n".join(lines)


def main():
    samples = [
        "Contact us at info@example.com or support@test.org.",
        "No emails here.",
        "Ping Info@Example.com, info@example.com and sales@shop.co.uk today!",
    ]
    for sample in samples:
        print("Text:", sample)
        # The raw scan keeps duplicates, so print it before the grouped report.
        matches = extract_emails(sample)
        print("Matches:", ", ".join(matches) if matches else "none")
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

