def is_valid_ipv4(ip_address: str) -> bool:
    # Split the IP address string by the dot character
    octets = ip_address.split('.')

    # An IPv4 address must have exactly four octets
    if len(octets) != 4:
        return False

    # Iterate through each octet to validate it
    for octet in octets:
        # Check if the octet is empty (e.g., '192..1.1')
        if not octet:
            return False
        # Check for leading zeros for multi-digit numbers (e.g., '01')
        if len(octet) > 1 and octet[0] == '0':
            return False
        try:
            # Convert the octet to an integer
            num = int(octet)
        except ValueError:
            # If conversion fails, it's not a valid number
            return False
        # Each octet must be between 0 and 255, inclusive
        if not (0 <= num <= 255):
            return False
    # If all checks pass, the IP address is valid
    return True

