def roman_to_int(roman_numeral: str) -> int:
    # Define the mapping of Roman symbols to their integer values.
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0  # Initialize the total integer value.
    prev_value = 0  # Initialize the value of the previous Roman numeral.

    # Iterate through the Roman numeral string from right to left.
    for char in reversed(roman_numeral):
        current_value = roman_map[char] # Get the integer value of the current symbol.

        # Check for subtractive cases (e.g., IV = 4, IX = 9).
        if current_value < prev_value:
            total -= current_value # Subtract if the current value is smaller than the previous.
        else:
            total += current_value # Otherwise, add the current value.

        prev_value = current_value # Update the previous value for the next iteration.

    return total # Return the final integer representation.

