def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after taking a percentage discount off the original."""
    price = float(original_price)
    percentage = float(discount_percentage)
    # A negative price has no meaning for a sale item, so reject it outright.
    if price < 0:
        raise ValueError("original_price must not be negative")
    # Discounts outside 0..100 would either raise the price or make it negative.
    if percentage < 0 or percentage > 100:
        raise ValueError("discount_percentage must be between 0 and 100")
    final_price = price * (1.0 - percentage / 100.0)
    # Money is rounded to cents, which also clears binary floating point noise.
    return round(final_price, 2)


def calculate_savings(original_price, discount_percentage):
    """Return how much money the discount saves on a single item."""
    discounted = calculate_discount_price(original_price, discount_percentage)
    # Deriving the saving from the discounted price makes both figures add up.
    return round(float(original_price) - discounted, 2)


def parse_discount(text):
    """Turn a human-written discount such as '15%' or ' 7.5 ' into a float."""
    cleaned = text.strip()
    # The trailing percent sign is optional in the input we accept.
    if cleaned.endswith("%"):
        cleaned = cleaned[:-1].strip()
    if not cleaned:
        raise ValueError("empty discount value")
    return float(cleaned)


def format_price(amount, currency="$"):
    """Format a number as a currency string with exactly two decimals."""
    return "{}{:.2f}".format(currency, amount)


def build_receipt_line(name, original_price, discount_text):
    """Describe one catalogue item after its discount has been applied."""
    percentage = parse_discount(discount_text)
    final_price = calculate_discount_price(original_price, percentage)
    saved = calculate_savings(original_price, percentage)
    # Zero-discount items read better without a "you save" clause.
    if saved == 0:
        return "{}: {} (no discount)".format(name, format_price(final_price))
    return "{}: {} -> {} (save {})".format(
        name,
        format_price(original_price),
        format_price(final_price),
        format_price(saved),
    )


def summarise_cart(items):
    """Return receipt lines plus the totals before and after discounts."""
    lines = []
    gross = 0.0
    net = 0.0
    for name, price, discount in items:
        lines.append(build_receipt_line(name, price, discount))
        gross += float(price)
        net += calculate_discount_price(price, parse_discount(discount))
    # Totals are rounded once at the end so the receipt adds up exactly.
    return lines, round(gross, 2), round(net, 2)


def main():
    catalogue = [
        ("Notebook", 100, "10%"),
        ("Mug", 50, "20"),
        ("Pen", 3.99, "0%"),
        ("Backpack", 79.95, "33.5%"),
    ]
    lines, gross, net = summarise_cart(catalogue)
    for line in lines:
        print(line)
    print("Total before discounts:", format_price(gross))
    print("Total after discounts:", format_price(net))
    # The difference is the shopper's overall saving across the whole cart.
    print("You saved:", format_price(round(gross - net, 2)))


if __name__ == "__main__":
    main()

