def has_all_unique_chars(s):
    # The public entry point only accepts text, so reject anything else loudly
    if not isinstance(s, str):
        raise TypeError("has_all_unique_chars expects a str")
    seen = set()
    for ch in s:
        # A character already recorded proves the string is not unique
        if ch in seen:
            return False
        seen.add(ch)
    # The loop finished without a collision, so all characters are distinct
    return True


def first_repeated_char(s):
    seen = set()
    for ch in s:
        # The first collision found while scanning left to right wins
        if ch in seen:
            return ch
        seen.add(ch)
    # Nothing repeated, so there is no culprit to report
    return None


def duplicate_counts(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    # Only characters seen more than once are interesting for a report
    return {ch: n for ch, n in counts.items() if n > 1}


def describe(s):
    if has_all_unique_chars(s):
        return "{!r}: all characters are unique".format(s)
    culprit = first_repeated_char(s)
    dupes = duplicate_counts(s)
    # Sort by descending count, then alphabetically, for a stable report
    ordered = sorted(dupes.items(), key=lambda item: (-item[1], item[0]))
    detail = ", ".join("{!r} x{}".format(ch, n) for ch, n in ordered)
    return "{!r}: not unique (first repeat {!r}; {})".format(s, culprit, detail)


def main():
    samples = [
        "abcde",
        "hello",
        "",
        "AaBbCc",
        "aA a",
        "mississippi",
    ]
    for sample in samples:
        print(describe(sample))
    # Summarise how many of the samples passed the uniqueness test
    unique_count = sum(1 for sample in samples if has_all_unique_chars(sample))
    print("{} of {} samples have all unique characters".format(unique_count, len(samples)))


if __name__ == "__main__":
    main()

