from datetime import date, timedelta


def _validate_date_parts(year, month, day):
    """Check that the three integers form a real calendar date."""
    # Reject non-integers early: bool is an int subclass but never a sensible date part
    for name, value in (("year", year), ("month", month), ("day", day)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be a plain int, got {type(value).__name__}")
    # date() itself knows about leap years and month lengths, so let it decide
    try:
        return date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"invalid date {year}-{month}-{day}: {exc}") from exc


def days_since(year, month, day):
    """Return the number of full days between the given past date and today."""
    given = _validate_date_parts(year, month, day)
    today = date.today()
    # A date in the future has no elapsed days yet, so treat it as a usage error
    if given > today:
        raise ValueError(f"{given.isoformat()} is in the future")
    # Subtracting two date objects yields a timedelta whose .days is already whole
    return (today - given).days


def describe_span(year, month, day):
    """Build a human-readable sentence about the elapsed time."""
    total = days_since(year, month, day)
    weeks, rest = divmod(total, 7)
    parts = []
    if weeks:
        parts.append(f"{weeks} week{'s' if weeks != 1 else ''}")
    # Show leftover days only when they add information, or when nothing else does
    if rest or not parts:
        parts.append(f"{rest} day{'s' if rest != 1 else ''}")
    given = date(year, month, day)
    return f"{given.isoformat()} was {total} day(s) ago ({' and '.join(parts)})"


def report(dates):
    """Describe every date, keeping bad input from aborting the whole run."""
    lines = []
    for parts in dates:
        try:
            lines.append(describe_span(*parts))
        except (TypeError, ValueError) as exc:
            # Keep the failing input visible so the reader can fix the data
            lines.append(f"{parts!r}: {exc}")
    return lines


def main():
    today = date.today()
    yesterday = today - timedelta(days=1)
    # Anchor the samples on today so the driver stays meaningful on any run
    samples = [
        (today.year, today.month, today.day),
        (yesterday.year, yesterday.month, yesterday.day),
        (today.year - 1, today.month, 1),
        (2023, 2, 30),
    ]
    for line in report(samples):
        print(line)


if __name__ == "__main__":
    main()

