class BankAccount:
    def __init__(self, initial_balance):
        # Initialize the account with a given initial balance.
        if not isinstance(initial_balance, (int, float)) or initial_balance < 0:
            # Ensure initial balance is a non-negative number.
            raise ValueError("Initial balance must be a non-negative number.")
        self.balance = initial_balance

    def deposit(self, amount):
        # Method to add funds to the account.
        if not isinstance(amount, (int, float)) or amount <= 0:
            # Deposits must be positive numbers.
            return False
        self.balance += amount
        # Return True for a successful deposit.
        return True

    def withdraw(self, amount):
        # Method to remove funds from the account.
        if not isinstance(amount, (int, float)) or amount <= 0:
            # Withdrawals must be positive numbers.
            return False
        if self.balance < amount:
            # Check for sufficient funds before withdrawal.
            return False  # Insufficient funds.
        self.balance -= amount
        # Return True for a successful withdrawal.
        return True

    def get_balance(self):
        # A helper method to retrieve the current account balance.
        return self.balance

