import math


# Un triángulo necesita tres lados estrictamente positivos
def is_valid_triangle(a, b, c):
    sides = (a, b, c)
    if any(side <= 0 for side in sides):
        return False
    # Desigualdad estricta: la igualdad significa que el triángulo se colapsa en una línea
    longest = max(sides)
    return sum(sides) - longest > longest


def triangle_area(a, b, c):
    if not is_valid_triangle(a, b, c):
        return 0.0
    s = (a + b + c) / 2.0
    radicand = s * (s - a) * (s - b) * (s - c)
    # El ruido de punto flotante puede empujar un producto casi degenerado por debajo de cero
    if radicand <= 0.0:
        return 0.0
    return math.sqrt(radicand)


def classify(a, b, c):
    if not is_valid_triangle(a, b, c):
        return "not a triangle"
    sides = sorted((a, b, c))
    # Comparar con una tolerancia para que sumas del estilo 0.1 + 0.2 sigan contando como iguales
    equal_pairs = sum(
        1 for x, y in ((sides[0], sides[1]), (sides[1], sides[2]))
        if math.isclose(x, y, rel_tol=1e-9, abs_tol=1e-12)
    )
    # Dos pares adyacentes iguales significan que los tres lados coinciden
    if equal_pairs == 2:
        return "equilateral"
    if equal_pairs == 1:
        return "isosceles"
    return "scalene"


# Aceptar longitudes de lados separadas tanto por comas como por espacios
def parse_sides(text):
    parts = text.replace(",", " ").split()
    # El llamador debe proporcionar exactamente tres números, ni más ni menos
    if len(parts) != 3:
        raise ValueError("expected exactly three side lengths, got %d" % len(parts))
    return tuple(float(part) for part in parts)


# Construir un informe de una sola línea para una única línea de entrada
def describe(text):
    a, b, c = parse_sides(text)
    area = triangle_area(a, b, c)
    kind = classify(a, b, c)
    return "sides %g, %g, %g -> %s, area %.4f" % (a, b, c, kind, area)


def main():
    samples = [
        "3 4 5",
        "1 1 10",
        "2, 2, 2",
        "5 5 8",
        "0 4 5",
        "1 2 3",
        "7 8 9.5",
        "4 5",
    ]
    for sample in samples:
        try:
            print(describe(sample))
        # Una entrada mal formada no debería abortar todo el informe
        except ValueError as exc:
            print("skipping %r: %s" % (sample, exc))


if __name__ == "__main__":
    main()

