class ToDoList:
    def __init__(self):
        # Initialize an empty dictionary to store tasks and their completion status.
        self.tasks = {}

    def add_task(self, task_name):
        # Add a new task to the dictionary, initially marked as not completed (False).
        self.tasks[task_name] = False

    def mark_completed(self, task_name):
        # Check if the task exists before trying to mark it.
        if task_name in self.tasks:
            # Mark the specified task as completed (True).
            self.tasks[task_name] = True
        else:
            # Optionally, handle the case where the task is not found.
            print(f"Task '{task_name}' not found.")

    def get_pending_tasks(self):
        # Initialize an empty list to store the names of pending tasks.
        pending_list = []
        # Iterate through all tasks in the dictionary.
        for task, completed in self.tasks.items():
            # If a task is not completed, add its name to the pending list.
            if not completed:
                pending_list.append(task)
        # Return the list of all pending (uncompleted) tasks.
        return pending_list

# Example usage as specified in the problem description:
# todo = ToDoList()
# todo.add_task('Buy milk')
# todo.add_task('Walk dog')
# todo.mark_completed('Buy milk')
# print(todo.get_pending_tasks()) # Expected: ['Walk dog']

