class ToDoList:
    def __init__(self):
        # Inicializa un diccionario vacío para almacenar las tareas y su estado de finalización.
        self.tasks = {}

    def add_task(self, task_name):
        # Agrega una nueva tarea al diccionario, inicialmente marcada como no completada (False).
        self.tasks[task_name] = False

    def mark_completed(self, task_name):
        # Verifica si la tarea existe antes de intentar marcarla.
        if task_name in self.tasks:
            # Marca la tarea especificada como completada (True).
            self.tasks[task_name] = True
        else:
            # Opcionalmente, maneja el caso en que la tarea no se encuentra.
            print(f"Task '{task_name}' not found.")

    def get_pending_tasks(self):
        # Inicializa una lista vacía para almacenar los nombres de las tareas pendientes.
        pending_list = []
        # Itera a través de todas las tareas en el diccionario.
        for task, completed in self.tasks.items():
            # Si una tarea no está completada, agrega su nombre a la lista de pendientes.
            if not completed:
                pending_list.append(task)
        # Devuelve la lista de todas las tareas pendientes (no completadas).
        return pending_list

