# Temperature conversion utilities supporting Celsius, Fahrenheit and Kelvin.

ABSOLUTE_ZERO_C = -273.15

# Canonical unit names used for human-readable reporting.
UNIT_NAMES = {'C': 'Celsius', 'F': 'Fahrenheit', 'K': 'Kelvin'}


def _to_celsius(value, unit):
    # Celsius is the pivot scale, so every input is first mapped onto it.
    if unit == 'C':
        return float(value)
    if unit == 'F':
        return (float(value) - 32.0) * 5.0 / 9.0
    # Kelvin differs from Celsius only by a constant offset.
    return float(value) + ABSOLUTE_ZERO_C


def _from_celsius(celsius, unit):
    if unit == 'C':
        return celsius
    if unit == 'F':
        return celsius * 9.0 / 5.0 + 32.0
    return celsius - ABSOLUTE_ZERO_C


def convert_temperature(value, unit_from, unit_to):
    unit_from = unit_from.strip().upper()
    unit_to = unit_to.strip().upper()
    # A same-scale request still needs to come back as a float.
    if unit_from == unit_to:
        return float(value)
    celsius = _to_celsius(value, unit_from)
    result = _from_celsius(celsius, unit_to)
    # Round away binary-float noise such as 0.9999999999999998 for 1 degree.
    return round(result, 10)


def is_physically_possible(value, unit):
    # Nothing can be colder than absolute zero on any of the three scales.
    return _to_celsius(value, unit) >= ABSOLUTE_ZERO_C


def format_conversion(value, unit_from, unit_to):
    converted = convert_temperature(value, unit_from, unit_to)
    source = UNIT_NAMES[unit_from.strip().upper()]
    target = UNIT_NAMES[unit_to.strip().upper()]
    # Two decimals are enough for a readable report line.
    return "%.2f %s = %.2f %s" % (value, source, converted, target)


def convert_series(values, unit_from, unit_to):
    converted = []
    for value in values:
        # Skip readings that no thermometer could ever have produced.
        if not is_physically_possible(value, unit_from):
            continue
        converted.append(convert_temperature(value, unit_from, unit_to))
    return converted


def main():
    print(format_conversion(0, 'C', 'F'))
    print(format_conversion(273.15, 'K', 'C'))
    print(format_conversion(98.6, 'F', 'C'))

    # A small batch where one reading is below absolute zero and gets dropped.
    readings = [-40.0, 0.0, 21.5, -300.0, 100.0]
    kelvins = convert_series(readings, 'C', 'K')
    print("Valid Kelvin readings:", kelvins)

    # The coldest surviving reading is the interesting summary value.
    print("Coldest: %.2f K" % min(kelvins))


if __name__ == '__main__':
    main()

