def check_password_strength(password):
    # Inicializar banderas de criterios
    has_upper = False
    has_lower = False
    has_digit = False

    # Iterar a través de los caracteres para verificar diferentes tipos
    for char in password:
        if 'A' <= char <= 'Z':
            has_upper = True
        elif 'a' <= char <= 'z':
            has_lower = True
        elif '0' <= char <= '9':
            has_digit = True

    # Contar cuántos de los tres criterios específicos se cumplen
    met_criteria_count = sum([has_upper, has_lower, has_digit])

    # Verificar las condiciones de contraseña 'Fuerte'
    if len(password) >= 8 and has_upper and has_lower and has_digit:
        return 'Strong'

    # Verificar las condiciones de contraseña 'Media'
    # Esto incluye la longitud y al menos dos de los tres tipos de caracteres
    elif len(password) >= 6 and met_criteria_count >= 2:
        return 'Medium'

    # Si no se cumplen las condiciones 'Fuerte' ni 'Media', es 'Débil'
    else:
        return 'Weak'

