def calculate_average(numbers):
    # Una muestra vacía no tiene media, por lo que la tarea define el resultado como 0.0
    if not numbers:
        return 0.0
    # float() garantiza un resultado flotante incluso cuando todos los elementos son enteros
    return float(sum(numbers)) / len(numbers)


def parse_numbers(text):
    # Las comas se tratan como simples separadores, así que funcionan tanto "1,2" como "1 2"
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        try:
            values.append(float(token))
        except ValueError:
            # Se vuelve a lanzar con el token problemático para que quien llama pueda informarlo
            raise ValueError("not a number: %r" % token)
    return values


def deviations(numbers):
    # La distancia con signo de cada valor respecto a la media de toda la muestra
    mean = calculate_average(numbers)
    return [value - mean for value in numbers]


def largest_deviation(numbers):
    # max() necesita una secuencia no vacía, de ahí la protección para la muestra vacía
    if not numbers:
        return 0.0
    return max(deviations(numbers), key=abs)


def format_report(label, numbers):
    # Primero el encabezado, luego las cifras resumen, y después una línea por valor
    lines = ["%s (%d value(s))" % (label, len(numbers))]
    lines.append("  average : %.4f" % calculate_average(numbers))
    # La mayor diferencia respecto a la media es una pista económica sobre la dispersión
    lines.append("  spread  : %.4f" % largest_deviation(numbers))
    for value, delta in zip(numbers, deviations(numbers)):
        # Un signo inicial hace evidente la dirección de cada desviación
        lines.append("    %10.4f  (%+.4f)" % (value, delta))
    return "\n".join(lines)


def main():
    samples = [
        ("first example", "1, 2, 3, 4, 5"),
        ("second example", "10 20"),
        ("empty sample", ""),
        ("broken input", "4 5 six"),
    ]
    for label, raw in samples:
        try:
            numbers = parse_numbers(raw)
        except ValueError as exc:
            # Una entrada incorrecta no debería detener los demás conjuntos de datos
            print("%s: skipped (%s)" % (label, exc))
            continue
        print(format_report(label, numbers))
        # Una línea en blanco mantiene legibles los informes consecutivos
        print()


