import re
import sys
from collections import Counter

# A hashtag is '#' followed by one or more alphanumeric characters.
HASHTAG_RE = re.compile(r"#([0-9A-Za-z]+)")


def extract_hashtags(text):
    """Return every hashtag in `text`, without the '#', in original casing."""
    # Reject non-string input early so callers get a clear error instead of a regex failure.
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %r" % type(text).__name__)
    # findall already yields group 1, i.e. the tag body without the '#'.
    return HASHTAG_RE.findall(text)


def unique_hashtags(text):
    """Hashtags with case-insensitive duplicates removed, keeping first occurrence."""
    seen = set()
    result = []
    for tag in extract_hashtags(text):
        # Comparison is done in lowercase, but the stored value keeps its original casing.
        key = tag.lower()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result


def count_hashtags(text):
    """Map the lowercase form of each hashtag to how often it appears."""
    return Counter(tag.lower() for tag in extract_hashtags(text))


def format_report(text):
    """Build a short human-readable summary of the hashtags found in `text`."""
    tags = extract_hashtags(text)
    if not tags:
        # Nothing matched: report it explicitly rather than printing an empty table.
        return "no hashtags found"
    counts = count_hashtags(text)
    lines = ["%d hashtag(s), %d unique" % (len(tags), len(counts))]
    for tag in unique_hashtags(text):
        # Show the original casing but the count aggregated case-insensitively.
        lines.append("  #%-20s x%d" % (tag, counts[tag.lower()]))
    return "\n".join(lines)


def main(argv):
    # Text comes from the command line when given, otherwise it is read from stdin.
    if len(argv) > 1:
        text = " ".join(argv[1:])
    else:
        text = sys.stdin.read()
    print(format_report(text))
    tags = extract_hashtags(text)
    # The plain list is what the specified API returns, so print it verbatim too.
    print("extract_hashtags ->", tags)
    # Exit status tells a shell caller whether anything was found.
