import re
import sys
from collections import Counter

# Un hashtag es '#' seguido de uno o más caracteres alfanuméricos.
HASHTAG_RE = re.compile(r"#([0-9A-Za-z]+)")


def extract_hashtags(text):
    """Return every hashtag in `text`, without the '#', in original casing."""
    # Rechaza pronto la entrada que no sea cadena para que quien llame reciba un error claro en vez de un fallo de la expresión regular.
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %r" % type(text).__name__)
    # findall ya devuelve el grupo 1, es decir, el cuerpo de la etiqueta sin el '#'.
    return HASHTAG_RE.findall(text)


def unique_hashtags(text):
    """Hashtags with case-insensitive duplicates removed, keeping first occurrence."""
    seen = set()
    result = []
    for tag in extract_hashtags(text):
        # La comparación se hace en minúsculas, pero el valor almacenado conserva sus mayúsculas y minúsculas originales.
        key = tag.lower()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result


def count_hashtags(text):
    """Map the lowercase form of each hashtag to how often it appears."""
    return Counter(tag.lower() for tag in extract_hashtags(text))


def format_report(text):
    """Build a short human-readable summary of the hashtags found in `text`."""
    tags = extract_hashtags(text)
    if not tags:
        # Nada coincidió: informarlo explícitamente en lugar de imprimir una tabla vacía.
        return "no hashtags found"
    counts = count_hashtags(text)
    lines = ["%d hashtag(s), %d unique" % (len(tags), len(counts))]
    for tag in unique_hashtags(text):
        # Muestra las mayúsculas y minúsculas originales pero el recuento agregado sin distinguirlas.
        lines.append("  #%-20s x%d" % (tag, counts[tag.lower()]))
    return "\n".join(lines)


def main(argv):
    # El texto viene de la línea de comandos cuando se proporciona; en caso contrario se lee de stdin.
    if len(argv) > 1:
        text = " ".join(argv[1:])
    else:
        text = sys.stdin.read()
    print(format_report(text))
    tags = extract_hashtags(text)
    # La lista simple es lo que devuelve la API especificada, así que imprímela también literalmente.
    print("extract_hashtags ->", tags)
    # El estado de salida indica a quien llame desde el shell si se encontró algo.
    return 0 if tags else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

