def validate_inputs(data, window_size):
    # A non-sequence input cannot be windowed at all, so reject it outright.
    if not isinstance(data, (list, tuple)):
        raise TypeError("data must be a list or tuple of numbers")
    # Booleans are ints in Python, but they are never a meaningful window size.
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an int")
    # A window of zero or negative length has no defined average.
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    for index, value in enumerate(data):
        # Strings and complex numbers would silently break the running sum.
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("data[%d] is not a real number" % index)


def calculate_sma_fixed_window(data, window_size):
    validate_inputs(data, window_size)
    # Not enough points to fill even one window, so there is nothing to report.
    if window_size > len(data):
        return []
    # Seed the running total with the first complete window.
    window_sum = float(sum(data[:window_size]))
    averages = [window_sum / window_size]
    for index in range(window_size, len(data)):
        # Slide the window: add the new point, drop the one that fell out.
        window_sum += data[index] - data[index - window_size]
        averages.append(window_sum / window_size)
    return averages


def align_with_data(data, window_size):
    averages = calculate_sma_fixed_window(data, window_size)
    # Without any complete window the whole series has undefined averages.
    if not averages:
        return [(value, None) for value in data]
    # The first window_size - 1 points precede the first complete window.
    aligned = [(value, None) for value in data[:window_size - 1]]
    for value, average in zip(data[window_size - 1:], averages):
        aligned.append((value, average))
    return aligned


def format_report(data, window_size):
    lines = ["idx  value      sma(%d)" % window_size]
    for index, (value, average) in enumerate(align_with_data(data, window_size)):
        # Undefined averages are shown as a dash rather than a misleading zero.
        shown = "-" if average is None else "%.4f" % average
        lines.append("%3d  %-9s  %s" % (index, value, shown))
    return "\n".join(lines)


def main():
    series = [10, 20, 30, 40, 50, 60, 70]
    for window_size in (3, 4):
        print(format_report(series, window_size))
        print()


if __name__ == "__main__":
    main()

