import sys


def contains_sublist(main_list, sub_list):
    # An empty pattern is trivially present, so answer before touching indices
    if not sub_list:
        return True
    return find_sublist(main_list, sub_list) != -1


def find_sublist(main_list, sub_list, start=0):
    n, m = len(main_list), len(sub_list)
    # A pattern longer than what is left of the list can never fit
    if m == 0 or m > n - start:
        return -1
    for i in range(max(start, 0), n - m + 1):
        # Compare the window element by element; slicing would copy needlessly
        if all(main_list[i + j] == sub_list[j] for j in range(m)):
            return i
    return -1


def count_sublists(main_list, sub_list, overlapping=True):
    # Counting an empty pattern is meaningless, so report zero matches
    if not sub_list:
        return 0
    count = 0
    index = find_sublist(main_list, sub_list)
    while index != -1:
        count += 1
        # Overlapping search advances one step; otherwise skip the whole match
        step = 1 if overlapping else len(sub_list)
        index = find_sublist(main_list, sub_list, index + step)
    return count


def describe(main_list, sub_list):
    if not sub_list:
        # The empty pattern is present but has no meaningful position
        return "[] is contained in every list (position 0 by convention)"
    position = find_sublist(main_list, sub_list)
    if position == -1:
        return "%r is not contained in %r" % (sub_list, main_list)
    total = count_sublists(main_list, sub_list)
    # Pluralise the word "time" so the report reads naturally
    times = "time" if total == 1 else "times"
    return "%r found in %r at index %d (%d %s)" % (
        sub_list, main_list, position, total, times)


def parse_list(text):
    items = []
    for token in text.split(","):
        token = token.strip()
        # Blank fields come from empty input or trailing commas and are dropped
        if not token:
            continue
        try:
            items.append(int(token))
        except ValueError:
            # Anything that is not an integer is kept as a plain string element
            items.append(token)
    return items


def main(argv):
    if len(argv) != 3:
        print("usage: %s <main-list> <sub-list>" % argv[0])
        print("lists are comma separated, e.g. \"1,2,3,4,5\" \"2,3\"")
        return 2
    main_list = parse_list(argv[1])
    sub_list = parse_list(argv[2])
    print("contains:", contains_sublist(main_list, sub_list))
    print(describe(main_list, sub_list))
    if sub_list:
        # Both counting modes only make sense for a non-empty pattern
        print("disjoint matches:", count_sublists(main_list, sub_list, False))
