import sys


def contains_sublist(main_list, sub_list):
    # Un patrón vacío está presente trivialmente, así que responde antes de tocar los índices
    if not sub_list:
        return True
    return find_sublist(main_list, sub_list) != -1


def find_sublist(main_list, sub_list, start=0):
    n, m = len(main_list), len(sub_list)
    # Un patrón más largo que lo que queda de la lista nunca puede encajar
    if m == 0 or m > n - start:
        return -1
    for i in range(max(start, 0), n - m + 1):
        # Compara la ventana elemento por elemento; el corte copiaría innecesariamente
        if all(main_list[i + j] == sub_list[j] for j in range(m)):
            return i
    return -1


def count_sublists(main_list, sub_list, overlapping=True):
    # Contar un patrón vacío no tiene sentido, así que informa de cero coincidencias
    if not sub_list:
        return 0
    count = 0
    index = find_sublist(main_list, sub_list)
    while index != -1:
        count += 1
        # La búsqueda con solapamiento avanza un paso; si no, salta toda la coincidencia
        step = 1 if overlapping else len(sub_list)
        index = find_sublist(main_list, sub_list, index + step)
    return count


def describe(main_list, sub_list):
    if not sub_list:
        # El patrón vacío está presente pero no tiene una posición significativa
        return "[] is contained in every list (position 0 by convention)"
    position = find_sublist(main_list, sub_list)
    if position == -1:
        return "%r is not contained in %r" % (sub_list, main_list)
    total = count_sublists(main_list, sub_list)
    # Pluraliza la palabra "time" para que el informe se lea con naturalidad
    times = "time" if total == 1 else "times"
    return "%r found in %r at index %d (%d %s)" % (
        sub_list, main_list, position, total, times)


def parse_list(text):
    items = []
    for token in text.split(","):
        token = token.strip()
        # Los campos en blanco provienen de una entrada vacía o de comas finales y se descartan
        if not token:
            continue
        try:
            items.append(int(token))
        except ValueError:
            # Todo lo que no sea un entero se conserva como un elemento de cadena simple
            items.append(token)
    return items


def main(argv):
    if len(argv) != 3:
        print("usage: %s <main-list> <sub-list>" % argv[0])
        print("lists are comma separated, e.g. \"1,2,3,4,5\" \"2,3\"")
        return 2
    main_list = parse_list(argv[1])
    sub_list = parse_list(argv[2])
    print("contains:", contains_sublist(main_list, sub_list))
    print(describe(main_list, sub_list))
    if sub_list:
        # Ambos modos de conteo solo tienen sentido para un patrón no vacío
        print("disjoint matches:", count_sublists(main_list, sub_list, False))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

