import re
from datetime import date

# Dates are stored in ISO order so plain string sorting is also chronological.
DATE_PATTERN = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")


def parse_date(date_str):
    # Validate an ISO date string and return it as a datetime.date.
    match = DATE_PATTERN.match(date_str)
    if match is None:
        raise ValueError(f"date must look like 'YYYY-MM-DD', got {date_str!r}")
    year, month, day = (int(part) for part in match.groups())
    # date() rejects impossible calendar days such as 2023-02-30.
    return date(year, month, day)


def add_calendar_event(calendar, date_str, event_description):
    # Reject malformed keys here so the calendar never gets a bogus date.
    parse_date(date_str)
    description = event_description.strip()
    if not description:
        raise ValueError("event description must not be empty")
    # setdefault creates the list on first use and reuses it afterwards.
    calendar.setdefault(date_str, []).append(description)


def events_on(calendar, date_str):
    # Copy the list so callers cannot mutate the calendar by accident.
    return list(calendar.get(date_str, []))


def busiest_day(calendar):
    if not calendar:
        return None
    # Ties are broken by the earlier date thanks to the sorted keys.
    return max(sorted(calendar), key=lambda day: len(calendar[day]))


def format_calendar(calendar):
    lines = []
    for date_str in sorted(calendar):
        day = parse_date(date_str)
        # %A gives the weekday name, which makes the agenda easier to scan.
        lines.append(f"{date_str} ({day.strftime('%A')}):")
        for position, description in enumerate(calendar[date_str], start=1):
            lines.append(f"  {position}. {description}")
    return "\n".join(lines)


def main():
    cal = {}
    schedule = [
        ('2023-10-26', 'Meeting'),
        ('2023-10-26', 'Lunch'),
        ('2023-10-27', 'Dentist'),
        ('2023-10-25', 'Code review'),
    ]
    for date_str, description in schedule:
        add_calendar_event(cal, date_str, description)
    print(format_calendar(cal))
    # The busiest day is reported separately as a small summary.
    print(f"Busiest day: {busiest_day(cal)}")
    print(f"Events on 2023-10-26: {events_on(cal, '2023-10-26')}")
    try:
        add_calendar_event(cal, '2023-13-01', 'Impossible month')
    except ValueError as error:
        # Bad input is reported but leaves the existing calendar untouched.
        print(f"Rejected: {error}")


if __name__ == '__main__':
    main()

