def merge_dicts(d1, d2):
    # Validate early so callers get a clear error instead of a confusing one later
    for name, candidate in (("d1", d1), ("d2", d2)):
        if not isinstance(candidate, dict):
            raise TypeError(f"{name} must be a dict, got {type(candidate).__name__}")
    merged = dict(d1)
    # The second dictionary wins on conflicting keys
    merged.update(d2)
    return merged


def merge_all(dicts):
    # Fold merge_dicts over the sequence, left to right
    result = {}
    for d in dicts:
        # Each step lets later dictionaries override the accumulated result
        result = merge_dicts(result, d)
    return result


def deep_merge(d1, d2):
    # Same precedence as merge_dicts, but nested dictionaries are combined
    merged = merge_dicts(d1, d2)
    for key, value in d2.items():
        original = d1.get(key)
        # Only recurse when both sides hold dicts; otherwise d2's value stands
        if isinstance(original, dict) and isinstance(value, dict):
            merged[key] = deep_merge(original, value)
    return merged


def conflicting_keys(d1, d2):
    shared = set(d1) & set(d2)
    # Sorting by repr keeps the report stable for mixed key types
    return sorted(shared, key=repr)


def format_merge_report(d1, d2):
    # Build a short human-readable summary of a merge
    merged = merge_dicts(d1, d2)
    lines = [f"merged: {merged}"]
    overridden = conflicting_keys(d1, d2)
    if overridden:
        for key in overridden:
            # Show what the key used to be and what d2 replaced it with
            lines.append(f"  {key!r}: {d1[key]!r} -> {d2[key]!r}")
    else:
        lines.append("  no overlapping keys")
    return "\n".join(lines)


def main():
    print(format_merge_report({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
    print(format_merge_report({'x': 10}, {'y': 20}))

    defaults = {'host': 'localhost', 'port': 80, 'debug': False}
    env = {'port': 8080}
    cli = {'debug': True}
    # Later sources have the highest priority: defaults < env < cli
    print("config:", merge_all([defaults, env, cli]))

    base = {'db': {'host': 'localhost', 'port': 5432}, 'retries': 3}
    override = {'db': {'port': 5433}}
    # A plain merge would drop 'host', deep_merge keeps it
    print("shallow:", merge_dicts(base, override))
    print("deep:   ", deep_merge(base, override))


if __name__ == "__main__":
    main()

