            raise IndexError("dequeue from an empty queue")
        # Eliminar el índice 0 mantiene intacto el orden FIFO.
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            raise IndexError("peek into an empty queue")
        return self._items[0]

